import {el,knob,slider} from './controls.js';
import {defaultPatch,parsePatch,savePatch,loadPatch} from './patches.js';
import {SignalGraphics} from './graphics.js';
const $=id=>document.getElementById(id),notice=text=>{$('notice').textContent=text;};
let metadata,patch,formatter,module,context,node,gain,playing=false,starting=false,generation=0,moves=0,effects=0,accentEditing=false;
const bindings=new Map(),notes=['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B'],duckNames=['CHORD','PINGS','BASS','PERCUSSION','VINYL','SPACE'];
const graphics=new SignalGraphics($('scope')),stats={statuses:0,peak:0,error:null};
const send=m=>{if(node)node.port.postMessage(m)};
const bind=(key,update)=>{if(!bindings.has(key))bindings.set(key,[]);bindings.get(key).push(update)};
const update=(key,value)=>{for(const fn of bindings.get(key)||[])fn(value)};
const keyIndex=key=>metadata.params.find(p=>p.key===key)?.id;
const paramValue=key=>patch.params[keyIndex(key)];
function stringAt(pointer){const bytes=new Uint8Array(formatter.memory.buffer);let end=pointer;while(bytes[end])end++;return new TextDecoder().decode(bytes.subarray(pointer,end));}
function format(key,v){return formatter?stringAt(formatter.dub_param_text(keyIndex(key),v)):String(v);}
function setTempo(v){if(!Number.isFinite(v)||v<30||v>320)return;patch.tempo=v;const index=keyIndex('TEMPO'),p=metadata.params[index];patch.params[index]=Math.max(p.min,Math.min(p.max,Math.round(v)));$('tempo').value=v;update('TEMPO',v);send({type:'tempo',value:v});}
function setParam(key,v){if(key==='TEMPO'){setTempo(v);return;}const index=keyIndex(key);patch.params[index]=v;update(key,v);send({type:'param',index,value:v});if(key==='ROOT'||key==='MODE')refreshScale();if(key.startsWith('DPAT')||key.startsWith('DACC'))refreshGrid();if(key==='TEMPO'){patch.tempo=v;$('tempo').value=v;}}
function parameter(key,label){if(key==='TEMPO'){const c=knob({label:'TEMPO',min:30,max:320,step:.5,value:patch.tempo,reset:122,format:v=>v+' BPM',change:setTempo,id:'TEMPO'});bind('TEMPO',c.update);return c.root;}const p=metadata.params[keyIndex(key)],control=knob({label:label||p.name.toUpperCase(),min:p.min,max:p.max,value:patch.params[p.id],reset:p.default,format:v=>format(key,v),change:v=>setParam(key,v),id:key});bind(key,control.update);return control.root;}
function amount(index,large=false){const config={label:duckNames[index],min:0,max:100,value:patch.ducks[index],format:v=>v+'%',change:v=>{patch.ducks[index]=v;update('duck'+index,v);send({type:'duck',index,value:v})},id:'duck_'+index};const control=large?knob(config):slider(config);bind('duck'+index,control.update);return control.root;}
function recovery(){const control=slider({label:'RECOVERY',min:20,max:800,value:patch.recovery,format:v=>v+' ms',change:v=>{patch.recovery=v;update('recovery',v);send({type:'release',value:v})},id:'recovery',cls:'recovery-line'});bind('recovery',control.update);return control.root;}
function moduleCard(title,index,keys,bus,voice=false){const colours=['#c9e8a0','#84d7d4','#a999e1','#c493ba'];const card=el('section','module'+(voice?' voices':''));card.style.setProperty('--tone',colours[index%4]);const heading=el('h3','module-head');heading.append(el('small','',String(index+1).padStart(2,'0')),document.createTextNode(title),el('i','module-led'));const controls=el('div','knob-grid');keys.forEach(k=>controls.append(parameter(k)));card.append(heading,controls);if(title==='MIX'){card.append(recovery());const gr=el('span','gain-reduction','0.0 dB');gr.id='gain-reduction';card.append(gr);}const canvas=el('canvas');canvas.setAttribute('aria-hidden','true');card.append(canvas,el('span','bus-label','BUS / '+String(index+1).padStart(2,'0')));graphics.add(canvas,bus,index,colours[index%4]);return card;}
function choice(key,label,options){const root=el('label','choice'),select=el('select');select.setAttribute('aria-label',label);options.forEach((text,i)=>{const o=el('option','',text);o.value=i;select.append(o)});select.value=paramValue(key);select.onchange=()=>setParam(key,Number(select.value));bind(key,v=>select.value=v);root.append(el('span','',label),select);return root;}
function title(page,name,hint){page.append(el('h2','page-title',name),el('p','page-hint',hint));}
let drumButtons=[];
function refreshGrid(){for(const {button,lane,step} of drumButtons){const hit=!!(paramValue('DPAT'+lane)&(1<<step)),accent=!!(paramValue('DACC'+lane)&(1<<step));button.classList.toggle('hit',hit);button.classList.toggle('accent',accent);button.setAttribute('aria-pressed',hit);button.title=(hit?'Hit':'Rest')+(accent?', accented':'')+'. Shift-click changes accent.';}}
function buildPages(){
 const names=['PLAY','VOICES','CHORDS','DRUMS','PERFORM','DUCKING'],pages=[];
 names.forEach((name,i)=>{const tab=el('button','',name);tab.id='tab-'+i;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','page-'+i);const page=el('div','page');page.id='page-'+i;page.setAttribute('role','tabpanel');page.setAttribute('aria-labelledby',tab.id);$('pages').append(page);document.querySelector('.tabs').append(tab);pages.push(page);tab.onclick=()=>selectPage(i);tab.onkeydown=e=>{let to=i;if(e.key==='ArrowRight')to=(i+1)%names.length;else if(e.key==='ArrowLeft')to=(i+names.length-1)%names.length;else if(e.key==='Home')to=0;else if(e.key==='End')to=names.length-1;else return;e.preventDefault();selectPage(to);$('tab-'+to).focus();};});
 function selectPage(index){pages.forEach((page,i)=>{page.hidden=index!==i;const tab=$('tab-'+i);tab.setAttribute('aria-selected',i===index);tab.tabIndex=i===index?0:-1;});}selectPage(0);
 const grid=el('div','module-grid');grid.append(moduleCard('MIX',0,['CHORD','PINGS','BASS','DRUMS','CRACKLE','DUCK'],5),moduleCard('CHORD',1,['CUTOFF','DECAY','STABS','DRIFT','EVOLVE','MOTION'],0),moduleCard('TEXTURE',2,['DENSITY','PTONE','POCT','GROOVE','BASSOCT','FIFTH'],6),moduleCard('SPACE',3,['ECHO','FEEDBACK','ETIME','REVERB','SIZE','CLOUD'],4));pages[0].append(grid);
 const strip=el('div','pump-strip'),heading=el('div','pump-heading','KICK → LAYERS');heading.append(el('small','','0% steady / 100% full master depth'));const amounts=el('div','pump-controls');for(let i=0;i<6;++i)amounts.append(amount(i));strip.append(heading,amounts);pages[0].append(strip);
 const voices=el('div','module-grid three');voices.append(moduleCard('CHORD VOICE',0,['CVOICE','CATT','CCOL','CRES','CENV','CALG','CFRAT','CFB','CFDEC','TUNE'],0,true),moduleCard('PING VOICE',1,['PVOICE','PTON','PRAT','PLEN','PBEND','PALG','PFRAT','PFB','PFDEC','TEMPO'],2,true),moduleCard('BASS VOICE',2,['BVOICE','BBITE','BSHAPE','BLEN','BSLIDE','BALG','BFRAT','BFB','BFDEC','GROOVE'],1,true));pages[1].append(voices);
 title(pages[2],'CHORD MEMORY','Empty slots hold the previous chord. Drift sets the time between changes.');const chords=el('div','chord-grid');for(let i=0;i<8;++i){const slot=el('div','chord-slot');slot.append(el('span','',String(i+1).padStart(2,'0')),choice('CR'+i,'ROOT '+(i+1),notes),choice('CQ'+i,'KIND '+(i+1),['Empty','Major','Minor','Sus 2','Sus 4','Diminished','Augmented']),choice('CX'+i,'EXTENSION '+(i+1),['Triad','6','7','Maj 7','9','11','Add 9']));chords.append(slot)}pages[2].append(chords,choice('PMODE','PROGRESSION',['Random','In order']));
 title(pages[3],'FIVE LANES / SIXTEEN STEPS','Tap a step for a hit. Use Accent edit or Shift-click for accents. Edits select Custom.');const drumChoices=el('div','choices-row');drumChoices.append(choice('KIT','KIT',metadata.voices[3]),choice('DMODE','PATTERN',['Generative','Custom']));const scroll=el('div','drum-scroll'),drums=el('div','drum-grid');drums.append(el('span'));for(let s=0;s<16;++s)drums.append(el('span','step-number',s+1));['KICK','SHAKER','OPEN HAT','RIM','CLAP'].forEach((name,lane)=>{drums.append(el('span','',name));for(let step=0;step<16;++step){const b=el('button');b.setAttribute('aria-label',name+' step '+(step+1));b.onclick=e=>{const key=(e.shiftKey||accentEditing?'DACC':'DPAT')+lane;let bits=(paramValue(key)&65535)^(1<<step);if(bits>32767)bits-=65536;setParam(key,bits);setParam('DMODE',1);};drumButtons.push({button:b,lane,step});drums.append(b)}});scroll.append(drums);const drumKnobs=el('div','drum-knobs');['KTUNE','KLEN','KPUNCH','HTONE','HATS','SWING','HITS','DACCENT','DCH0','DCH1','DCH2','DCH3','DCH4'].forEach(k=>drumKnobs.append(parameter(k)));const editAccents=el('button','','EDIT ACCENTS');editAccents.setAttribute('aria-pressed','false');editAccents.onclick=()=>{accentEditing=!accentEditing;editAccents.setAttribute('aria-pressed',accentEditing)};pages[3].append(drumChoices,editAccents,scroll,drumKnobs);refreshGrid();
 title(pages[4],'DUB MOVES','Hold a pad to perform. Release to return.');const moveGrid=el('div','perform-grid moves'),fxGrid=el('div','perform-grid');['THROW','OPEN','SHUT','DROP','PUSH ECHO'].forEach((name,i)=>moveGrid.append(pad(name,i,false)));metadata.effects.forEach((name,i)=>fxGrid.append(pad(name.toUpperCase(),i,true)));pages[4].append(moveGrid,el('h3','page-title','EFFECTS GRID'),fxGrid);
 title(pages[5],'KICK → LAYERS','Choose how much each layer pumps. The kick stays full.');const ducks=el('div','duck-grid');for(let i=0;i<6;++i)ducks.append(amount(i,true));const shared=el('div','duck-shared');shared.append(parameter('DUCK','MASTER DUCK'),recovery());pages[5].append(ducks,shared);
}
const pads=[];
function pad(name,index,fx){const b=el('button','',name);b.setAttribute('aria-pressed','false');const set=on=>{const bit=1<<index;if(fx)effects=on?effects|bit:effects&~bit;else moves=on?moves|bit:moves&~bit;b.setAttribute('aria-pressed',on);send({type:'config',key:fx?4:3,value:fx?effects:moves});};b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();b.focus();b.setPointerCapture(e.pointerId);set(true)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>set(false));b.onkeydown=e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();set(true)}};b.onkeyup=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();set(false)}};b.onblur=()=>set(false);pads.push(b);return b;}
function clearMomentary(){moves=effects=0;pads.forEach(b=>b.setAttribute('aria-pressed','false'));send({type:'config',key:3,value:0});send({type:'config',key:4,value:0});}
window.addEventListener('blur',clearMomentary);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMomentary()});
function refreshScale(){const root=paramValue('ROOT'),mode=paramValue('MODE'),pool=(patch.scale||metadata.modes[mode].pool)|1;$('root').value=root;$('mode').value=patch.scale?8:mode;[...$('scale').children].forEach((b,i)=>{b.textContent=notes[(root+i)%12];b.setAttribute('aria-pressed',!!(pool&(1<<i)));b.setAttribute('aria-label','Scale '+notes[(root+i)%12]);});[...$('mutes').children].forEach((b,i)=>b.setAttribute('aria-pressed',!(patch.mutes&(1<<i))));}
function refresh(){metadata.params.forEach(p=>update(p.key,patch.params[p.id]));patch.ducks.forEach((v,i)=>update('duck'+i,v));update('recovery',patch.recovery);$('piece').value=patch.piece;$('tempo').value=patch.tempo;update('TEMPO',patch.tempo);$('hold').setAttribute('aria-pressed',patch.hold);$('output').value=patch.output;$('output').style.setProperty('--slider-value',(100*(patch.output+48)/54)+'%');$('output-value').textContent=patch.output.toFixed(1)+' dB';$('patch-name').value=patch.name;refreshScale();refreshGrid();if(gain)gain.gain.setTargetAtTime(10**(patch.output/20),context.currentTime,.015);}
function applyPatch(value){patch=value;generation++;refresh();send({type:'patch',generation,value:patch,play:playing});}
function displayAudio(){const active=context?.state==='running'&&playing;$('audio-status').classList.toggle('running',active);$('audio-status').lastChild.textContent=starting?' STARTING':context?.state==='suspended'?' SUSPENDED':active?' RUNNING':node?' REST / TAILS':' AUDIO OFF';$('start').textContent=starting?'STARTING…':active?'STOP ■':node?'RUN ▶':'START AUDIO ▶';$('start').disabled=starting;}
async function startAudio(){
 if(starting)return;
 if(node){const wasSuspended=context.state!=='running';if(wasSuspended)await context.resume();playing=wasSuspended?true:!playing;send({type:'play',value:playing});displayAudio();return;}
 starting=true;displayAudio();notice('Starting audio…');
 try{
  if(!window.AudioContext||!window.AudioWorkletNode)throw Error('This browser does not support AudioWorklet. Try an up-to-date Chrome, Safari or Firefox.');
  try{context=new AudioContext({sampleRate:44100,latencyHint:'interactive'})}catch{context=new AudioContext({latencyHint:'interactive'})}
  const resume=context.resume();context.onstatechange=()=>displayAudio();await resume;
  await context.audioWorklet.addModule('audio-worklet.js');node=new AudioWorkletNode(context,'pxl-dub',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[2],processorOptions:{module}});
  gain=context.createGain();gain.gain.value=10**(patch.output/20);node.connect(gain).connect(context.destination);
  node.onprocessorerror=()=>{stats.error='Audio engine stopped';notice('Audio engine stopped. Click Start audio to retry.');playing=false;node.disconnect();node=null;context.close().catch(()=>{});displayAudio();};
  node.port.onmessage=event=>{const m=event.data;if(m.type!=='status')return;const values=new Float32Array(m.data);if(m.generation===generation){graphics.receive(values,10**(patch.output/20));patch.pings=Array.from(values.subarray(145,227));stats.statuses++;stats.peak=values[5];$('gain-reduction').textContent=(-20*Math.log10(Math.max(.001,1-values[6]))).toFixed(1)+' dB';const root=Math.max(0,Math.min(11,values[8]));const chordNotes=Array.from(values.subarray(11,15)).map(v=>notes[((Math.round(v)%12)+12)%12]);$('chord-status').replaceChildren(document.createTextNode(stringAt(formatter.dub_chord_text(root,...Array.from(values.subarray(11,15))))),el('small','',chordNotes.join(' / ')));$('phrase-status').textContent=['FULL','BREAK','GROOVE','THIN'][Math.round(values[9])]+ ' / '+String(Math.round(values[10])+1).padStart(2,'0')+':08';playing=values[16]===1;displayAudio();}node?.port.postMessage({type:'buffer',data:m.data},[m.data]);};
  playing=true;generation++;send({type:'patch',generation,value:patch,play:true});notice('The piece is running. Shape the layers, or set a different pump amount for each.');
 }catch(error){stats.error=error.message;playing=false;node?.disconnect();node=null;if(context&&context.state!=='closed')await context.close().catch(()=>{});notice(error.message||'Could not start audio. Try again.');}
 finally{starting=false;displayAudio();}
}
async function init(){
 metadata=await fetch('metadata.json').then(r=>{if(!r.ok)throw Error('Instrument controls could not load. Reload this page.');return r.json()});
 const bytes=await fetch('engine.wasm').then(r=>{if(!r.ok)throw Error('The audio engine could not load. Reload this page.');return r.arrayBuffer()});module=await WebAssembly.compile(bytes);formatter=new WebAssembly.Instance(module).exports;formatter.__wasm_call_ctors();formatter.dub_init();formatter.dub_piece(0);
 let storage;try{storage=window.localStorage}catch{storage={getItem(){return null},setItem(){throw Error('Storage unavailable')}}}patch=loadPatch(storage,metadata);
 metadata.pieces.forEach((p,i)=>{const option=el('option','',String(i+1).padStart(2,'0')+' / '+p.name.toUpperCase());option.value=i;$('piece').append(option)});
 notes.forEach((n,i)=>{const o=el('option','',n);o.value=i;$('root').append(o)});[...metadata.modes.map(m=>m.name),'Custom'].forEach((n,i)=>{const o=el('option','',n);o.value=i;$('mode').append(o)});
 for(let i=0;i<12;++i){const b=el('button');b.onclick=()=>{const mask=(patch.scale||metadata.modes[paramValue('MODE')].pool)|1;patch.scale=(mask^(1<<i))|1;send({type:'config',key:1,value:patch.scale});refreshScale()};$('scale').append(b)}
 ['CHORD','PINGS','BASS','KICK','HATS'].forEach((n,i)=>{const b=el('button','',n);b.setAttribute('aria-label',n+' enabled');b.onclick=()=>{patch.mutes^=1<<i;send({type:'config',key:0,value:patch.mutes});refreshScale()};$('mutes').append(b)});
 buildPages();refresh();$('start').onclick=()=>startAudio().catch(error=>notice(error.message));
 $('piece').onchange=()=>{const i=Number($('piece').value);patch={...patch,piece:i,name:metadata.pieces[i].name,params:[...metadata.pieces[i].params],tempo:metadata.pieces[i].params[keyIndex('TEMPO')],mutes:0,scale:0,hold:false,pings:null};applyPatch(patch);};
 $('root').onchange=()=>setParam('ROOT',Number($('root').value));$('mode').onchange=()=>{const mode=Number($('mode').value);if(mode<8){setParam('MODE',mode);patch.scale=0;}else patch.scale=metadata.modes[paramValue('MODE')].pool|1;send({type:'config',key:1,value:patch.scale});refreshScale();};
 $('tempo').onchange=()=>{const v=Number($('tempo').value);if(Number.isFinite(v)&&v>=30&&v<=320){setTempo(v)}else $('tempo').value=patch.tempo;};
 $('hold').onclick=()=>{patch.hold=!patch.hold;$('hold').setAttribute('aria-pressed',patch.hold);send({type:'config',key:2,value:patch.hold?1:0})};
 $('output').oninput=()=>{patch.output=Number($('output').value);$('output').style.setProperty('--slider-value',(100*(patch.output+48)/54)+'%');$('output-value').textContent=patch.output.toFixed(1)+' dB';if(gain)gain.gain.setTargetAtTime(10**(patch.output/20),context.currentTime,.015);};
 $('patch-name').oninput=()=>patch.name=$('patch-name').value;
 $('next').onclick=()=>send({type:'action',value:1});$('regrow').onclick=()=>{patch.pings=null;generation++;send({type:'action',generation,value:2});notice('A new pattern is growing.');};
 $('panic').onclick=()=>{playing=false;clearMomentary();send({type:'action',value:3});displayAudio();notice('Sound cleared. Click Run to continue.');};
 $('save').onclick=()=>notice(savePatch(storage,patch,metadata)?'Patch saved in this browser.':'Local storage is unavailable. Export the patch to keep it.');
 $('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(patch,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='PXL-Dub-patch.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Patch exported, including the generated loops.');};
 $('import').onclick=()=>$('patch-file').click();$('patch-file').onchange=async()=>{const file=$('patch-file').files[0];if(!file)return;try{if(file.size>65536)throw Error('Choose a patch smaller than64 KB.');applyPatch(parsePatch(await file.text(),metadata));notice('Patch loaded.')}catch(error){notice('Could not load patch: '+error.message)}finally{$('patch-file').value=''}};
 displayAudio();document.documentElement.dataset.ready='true';
 window.pxlDub={get context(){return context},get node(){return node},get patch(){return structuredClone(patch)},stats};
}
$('start').disabled=true;notice('Loading the instrument…');
init().then(()=>notice('Click Start audio to begin. PXL Dub makes its own notes; you steer the piece.')).catch(error=>{stats.error=error.message;notice(error.message);$('start').textContent='RELOAD TO RETRY';$('start').disabled=false;$('start').onclick=()=>location.reload();});
